'use strict';
(() => {
const lang=document.documentElement.lang,li={kk:0,ru:1,en:2}[lang]??0;
const t=(kk,ru,en)=>[kk,ru,en][li],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=2)=>Number(n).toLocaleString(lang==='kk'?'kk-KZ':lang==='ru'?'ru-RU':'en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const colors=['#247c64','#8b70af','#bd843b'],ids=['dt','rf','gb','xgb'],short={dt:'Decision Tree',rf:'Random Forest',gb:'Gradient Boosting',xgb:'XGBoost'};
const origins=[t('АҚШ','США','USA'),t('Еуропа','Европа','Europe'),t('Жапония','Япония','Japan')];
const labels=[t('Цилиндрлер','Цилиндры','Cylinders'),t('Қозғалтқыш көлемі','Объём двигателя','Displacement'),t('Қуат','Мощность','Horsepower'),t('Салмақ','Вес','Weight'),t('Үдеу уақыты','Время разгона','Acceleration time'),t('Жыл коды','Код года','Year code'),t('Шығу аймағы','Регион','Origin')],units=['','in³','hp','lb','s','',''];
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,main=document.getElementById('lesson'),dialog=document.getElementById('codeDialog'),copy=window.AUTO_COPY[lang]||window.AUTO_COPY.kk;
let data,codes,chapter=1,sample=0,stage={gb:0,xgb:0},origin='all',query='',missingOnly=false,page=0,pageSize=12,compareModel='xgb',worstOnly=false,timer=null;
const selected=()=>data.test[sample],isDataset=()=>location.hash==='#dataset';
function car(color='#247c64'){return `<svg class="car-art" viewBox="0 0 260 110" aria-hidden="true"><ellipse cx="130" cy="93" rx="111" ry="8" fill="#183b3010"/><path d="M18 70 30 48 67 43 93 18 164 18 193 46 232 54 244 73 240 86H20z" fill="${color}"/><path d="m79 43 21-19h28v20zm56-19h24l20 21h-44z" fill="#e7f0df"/><path d="M22 64h18M220 65h19" stroke="#e6c47b" stroke-width="6"/><path d="M61 52h141M132 48v30" stroke="#dce8d2" stroke-width="1" opacity=".45"/><circle cx="65" cy="84" r="18" fill="#183b30"/><circle cx="204" cy="84" r="18" fill="#183b30"/><circle cx="65" cy="84" r="9" fill="#dbe5d3"/><circle cx="204" cy="84" r="9" fill="#dbe5d3"/><path d="M4 107h252" stroke="#cdd9c3" stroke-dasharray="18 12" stroke-width="2"/></svg>`;}
const legend=()=>`<div class="legend">${origins.map((n,i)=>`<span><i class="dot" style="background:${colors[i]}"></i>${i+1} · ${n}</span>`).join('')}</div>`;
const tabs=(action,items,current)=>`<div class="segmented">${items.map(([v,l])=>`<button data-action="${action}" data-value="${v}" aria-pressed="${current===v}">${l}</button>`).join('')}</div>`;
const metrics=id=>{const m=data.models[id];return `<div class="reg-metrics"><div><small>MAE · MPG ↓</small><b>${fmt(m.mae)}</b></div><div><small>RMSE · MPG ↓</small><b>${fmt(m.rmse)}</b></div><div><small>R² ↑</small><b>${fmt(m.r2,3)}</b></div></div>`;};
const params=id=>`<div class="params">${Object.entries(data.models[id].params).map(([k,v])=>`<code>${esc(k.replace('model__',''))} = ${v===null?'None':esc(v)}</code>`).join('')}</div>`;
function prediction(id,pred=selected().pred[id]){const p=selected(),err=pred-p.y;return `<div class="outcome"><h3>${t('Таңдалған автомобильдің болжамы','Прогноз выбранного автомобиля','Prediction for the selected car')}</h3><div class="mpg-prediction">${fmt(pred)} <span>MPG</span></div><div class="actual-value">${t('Нақты мән','Фактическое значение','Actual value')}: <b>${fmt(p.y)} MPG</b></div><div class="mpg-meter"><i class="actual-marker" style="left:${Math.max(0,Math.min(100,p.y/50*100))}%"></i><i class="pred-marker" style="left:${Math.max(0,Math.min(100,pred/50*100))}%"></i></div><div class="range-ends"><span>0</span><span>25</span><span>50 MPG</span></div><div class="legend"><span><i class="dot" style="background:#8b70af"></i>${t('Нақты','Факт','Actual')}</span><span><i class="dot" style="background:#176e59"></i>${t('Болжам','Прогноз','Predicted')}</span></div><div class="prediction-error"><span>${t('Қате = болжам − нақты','Ошибка = прогноз − факт','Error = predicted − actual')}</span><b>${err>=0?'+':''}${fmt(err)} MPG</b></div><p class="footnote">${t('Бұл — бір автомобильдің қатесі. Төмендегі метрикалар 80 test автомобильдің бәрі бойынша есептелген.','Это ошибка одной машины. Метрики ниже рассчитаны по всем 80 автомобилям test.','This is one car’s error. The metrics below use all 80 test cars.')}</p></div>`;}
function sampleControls(play=true){const p=selected();return `<div class="sample-controls"><label for="sampleSelect">${t('Test автомобилі','Автомобиль из test','Test car')}<select id="sampleSelect">${data.test.map((r,i)=>`<option value="${i}" ${sample===i?'selected':''}>#${r.csvRow} · ${esc(r.name)}</option>`).join('')}</select></label><span class="mini-legend">${sample+1} / 80</span>${play?`<button class="button small" data-action="play">▷ ${t('Анимацияны көру','Запустить анимацию','Play animation')}</button>`:''}</div><div class="sample-measures auto-measures">${p.x.map((v,i)=>`<div><small>${labels[i]}</small><b>${i===6?origins[v-1]:v===null?'—':fmt(v,[0,5].includes(i)?0:1)} <span>${units[i]}</span></b></div>`).join('')}</div>${p.x[2]===null?`<p class="missing-notice">${t('Қуат мәні бос. Модель train медианасын қолданады','Мощность отсутствует. Модель использует медиану train','Horsepower is missing. The model uses the training median')}: ${fmt(data.meta.imputerMedian[2],1)} hp.</p>`:''}`;}
function trainScatter(){const x=v=>43+(v-1500)/4000*380,y=v=>255-(v-5)/45*220;return `<svg viewBox="0 0 455 300" role="img" aria-label="${t('318 train автомобильдің салмағы мен MPG','Вес и MPG 318 автомобилей train','Weight and MPG for 318 training cars')}">${[10,20,30,40,50].map(v=>`<path d="M43 ${y(v)}H423" stroke="#dce5d4"/><text x="35" y="${y(v)+3}" text-anchor="end" class="chart-label">${v}</text>`).join('')}${[1500,2500,3500,4500,5500].map(v=>`<text x="${x(v)}" y="274" text-anchor="middle" class="chart-label">${v}</text>`).join('')}<text x="43" y="17" class="chart-label">MPG ↑</text><text x="230" y="297" text-anchor="middle" class="chart-label">${labels[3]} (lb)</text>${data.train.map((r,i)=>`<circle class="scatter-dot" cx="${x(r.x[3])}" cy="${y(r.y)}" r="3.7" fill="${colors[r.x[6]-1]}" opacity=".75" style="--delay:${i%25*15}ms"><title>${esc(r.name)} · ${r.x[3]} lb · ${r.y} MPG</title></circle>`).join('')}</svg>`;}
function datasetOverview(){return `<div class="panel-heading"><div><h2>${t('Автомобиль қаншалықты үнемді?','Насколько экономичен автомобиль?','How fuel-efficient is a car?')}</h2><p>UCI AUTO MPG · 1970–1982 · REGRESSION</p></div><a class="button small" href="#dataset">▦ ${t('Датасетті ашу','Открыть датасет','Open dataset')}</a></div><div class="panel-body replay"><div class="data-stage"><div class="chart-card"><div class="chart-title">${t('Салмақ пен үнемділік · тек train','Вес и экономичность · только train','Weight and economy · training data only')}</div>${legend()}${trainScatter()}<p class="chart-sub">${t('Түс — шыққан аймақ. Ол мақсатты класс емес: мақсат — сан түріндегі MPG. Модельдер жеті белгіні қолданады.','Цвет обозначает регион, а не целевой класс. Цель — числовое значение MPG. Модели используют семь признаков.','Color indicates origin, not a target class. The target is numeric MPG. Models use seven inputs.')}</p></div><div><div class="car-hero">${car()}<span class="eyebrow">MILES PER GALLON</span><h3>${t('MPG жоғары —<br>жанармай аз кетеді.','Выше MPG —<br>экономичнее поездка.','Higher MPG.<br>Better fuel economy.')}</h3><p>${t('Бір галлон отынмен жүретін миль саны. Модель түрді емес, осы санды болжайды.','Количество миль на одном галлоне топлива. Модель предсказывает это число, а не категорию.','Miles traveled on one gallon of fuel. The model predicts this number, not a category.')}</p></div><div class="split-flow"><h3>${t('Бірдей дерек, әділ салыстыру','Общие данные, честное сравнение','Same data, fair comparison')}</h3><div class="split-stats"><div><b>398</b>${t('автомобиль','автомобилей','cars')}</div><div><b>7</b>${t('кіріс белгі','входных признаков','input features')}</div><div><b>1</b>${t('сандық мақсат','числовая цель','numeric target')}</div></div><div class="split-bar"><span></span><span></span></div><div class="split-labels"><span>TRAIN · 318 (~80%)</span><span>TEST · 80 (~20%)</span></div></div></div></div><div class="params">${data.meta.features.map(f=>`<code>${esc(f)}</code>`).join('')}</div><p class="footnote">${t('6 horsepower мәні бос: train медианасымен Pipeline ішінде толтырылады. car_name — тек атау, модельге берілмейді. origin бір-бірінен тәуелсіз 0/1 бағандарына айналады.','6 значений horsepower пропущены: Pipeline заполняет их медианой train. car_name — только название и не подаётся модели. origin кодируется отдельными столбцами 0/1.','6 horsepower values are missing: the Pipeline fills them with the training median. car_name is an identifier, excluded from the model. origin is one-hot encoded.')}</p><button class="button small" data-action="play">▷ ${t('Қайта көрсету','Повторить','Replay')}</button></div>`;}
function datasetTable(){return `<div class="panel-heading"><div><h2>Auto MPG · ${t('толық кесте','полная таблица','complete table')}</h2><p>UCI · ${t('Бастапқы деректер өзгертілмеген','Исходные пропуски сохранены','Original missing values preserved')}</p></div><a class="button small" href="#1">${t('Графикке өту','К графику','Explore chart')} ↗</a></div><div class="panel-body"><div class="dataset-summary"><div><b>398</b><span>${t('автомобиль','автомобилей','cars')}</span></div><div><b>9</b><span>${t('бастапқы баған','исходных столбцов','original columns')}</span></div><div><b>7</b><span>${t('кіріс белгі','входных признаков','input features')}</span></div><div><b>6</b><span>${t('қуат мәні бос','пропусков мощности','missing horsepower values')}</span></div></div><div class="data-tools"><label>${labels[6]}<select id="originFilter"><option value="all">${t('Барлығы','Все','All')}</option>${origins.map((v,i)=>`<option value="${i+1}" ${origin===String(i+1)?'selected':''}>${i+1} · ${v}</option>`).join('')}</select></label><label>${t('Атауы / CSV жолы','Название / строка CSV','Name / CSV row')}<input id="rowSearch" type="search" value="${esc(query)}" placeholder="ford / 153"></label><label>${t('Бір бетте','На странице','Rows per page')}<select id="pageSize">${[12,25,50,398].map(n=>`<option value="${n}" ${pageSize===n?'selected':''}>${n===398?t('Барлығы','Все','All'):n}</option>`).join('')}</select></label><label class="missing-check"><input id="missingOnly" type="checkbox" ${missingOnly?'checked':''}>${t('Бос мәндер · 6','С пропусками · 6','Missing values · 6')}</label><a class="button small" href="autompg-files/auto_mpg.csv" download>↓ CSV · 398</a></div><div id="datasetRows"></div><p class="footnote">${t('lb — фунт; in³ — текше дюйм; acceleration — 0–60 mph үдеу уақыты, секундпен. Жыл коды: 70 = 1970, 82 = 1982.','lb — фунты; in³ — кубические дюймы; acceleration — время разгона 0–60 mph в секундах. Код года: 70 = 1970, 82 = 1982.','lb = pounds; in³ = cubic inches; acceleration = 0–60 mph time in seconds. Year code: 70 = 1970, 82 = 1982.')}</p><p class="footnote">${t('«—» — бастапқы бос мән. Кестеде импутация жасалмайды. CSV жолы тақырыпты қосып есептеледі. CSV нөмірі мен train/test — қосымша анықтамалық бағандар.','«—» — исходный пропуск. В таблице он не заменяется медианой. Номер строки CSV учитывает заголовок. Номер CSV и train/test — дополнительные справочные столбцы.','“—” is an original missing value, not replaced in this table. CSV row numbers include the header. CSV row and train/test are added reference columns.')}</p></div>`;}
function drawRows(){const rows=data.raw.filter(r=>(origin==='all'||r.x[6]===Number(origin))&&(!missingOnly||r.x[2]===null)&&(!query||`${r.csvRow} ${r.name}`.toLowerCase().includes(query.toLowerCase())));page=Math.max(0,Math.min(page,Math.ceil(rows.length/pageSize)-1));document.getElementById('datasetRows').innerHTML=`<div class="table-scroll"><table class="data-table"><thead><tr>${['CSV',t('Автомобиль','Автомобиль','Car'),'MPG',...labels.map((v,i)=>v+(units[i]?' ('+units[i]+')':'')),t('Бөлік','Выборка','Split')].map(v=>`<th scope="col">${v}</th>`).join('')}</tr></thead><tbody>${rows.slice(page*pageSize,(page+1)*pageSize).map(r=>`<tr><td>#${r.csvRow}</td><td>${esc(r.name)}</td><td><b>${fmt(r.y,1)}</b></td>${r.x.map((v,i)=>`<td class="${v===null?'missing-cell':''}">${i===6?`${v} · ${origins[v-1]}`:v===null?'—':fmt(v,[0,5].includes(i)?0:1)}</td>`).join('')}<td>${r.split}</td></tr>`).join('')||`<tr><td colspan="11">${t('Жол табылмады','Строки не найдены','No matching rows')}</td></tr>`}</tbody></table></div><div class="pager"><span>${rows.length?`${page*pageSize+1}–${Math.min(rows.length,(page+1)*pageSize)}`:'0'} / ${rows.length}</span><div><button class="button small" data-action="prevRows" ${page===0?'disabled':''} aria-label="${t('Алдыңғы жолдар','Предыдущие строки','Previous rows')}">←</button><button class="button small" data-action="nextRows" ${(page+1)*pageSize>=rows.length?'disabled':''} aria-label="${t('Келесі жолдар','Следующие строки','Next rows')}">→</button></div></div>`;}
function treeFeature(i){return i<6?labels[i]+(units[i]?' ('+units[i]+')':''):`origin = ${origins[i-6]}`;}
function treeVisual(){const p=selected();return `<div class="panel-heading"><div><h2>${t('Шарттардан — MPG болжамына','От условий к прогнозу MPG','Follow the tree to an MPG prediction')}</h2><p>DecisionTreeRegressor · ${t('нақты шешім жолы','настоящий путь решения','actual fitted decision path')}</p></div><span class="status-chip">TEST RMSE · ${fmt(data.models.dt.rmse)} MPG</span></div>${sampleControls()}<div class="panel-body"><div class="model-stage"><div class="path">${p.dtPath.map((s,i)=>`<div class="path-node shown" data-step="${i}"><small>${t('Қадам','Шаг','Step')} ${i+1} · ${treeFeature(s.feature)}</small><b>${fmt(s.value,s.feature>=6?0:1)} ≤ ${fmt(s.threshold,2)}?</b> → ${s.left?t('ИӘ','ДА','YES'):t('ЖОҚ','НЕТ','NO')}</div><span class="path-arrow" aria-hidden="true">↓</span>`).join('')}<div class="path-node leaf shown" data-step="${p.dtPath.length}"><small>${t('Жапырақ: train MPG орташа мәні','Лист: среднее MPG объектов train','Leaf: mean training MPG')} · n=${p.dtLeaf.nSamples}</small><b>${fmt(p.dtLeaf.value)} MPG</b></div></div><div>${prediction('dt')}${metrics('dt')}${params('dt')}<p class="footnote">${t('Жапырақтағы орташа сан — болжам. ≤ сол тармаққа, > оң тармаққа өткізеді. origin үшін 0/1 индикаторы тексеріледі.','Среднее число в листе становится прогнозом. ≤ ведёт влево, > вправо. Для origin проверяется индикатор 0/1.','The leaf mean becomes the prediction. ≤ follows the left branch, > the right. origin splits test a 0/1 indicator.')}</p></div></div></div>`;}
function forestVisual(){const p=selected(),count=data.models.rf.params.n_estimators;return `<div class="panel-heading"><div><h2>${t('Көп ағаштың ортақ болжамы','Общий прогноз множества деревьев','Many trees, one average prediction')}</h2><p>${count} ${t('ағаштың MPG болжамдары орташаланады','прогнозов MPG усредняются','tree MPG predictions are averaged')}</p></div><span class="status-chip">TEST RMSE · ${fmt(data.models.rf.rmse)} MPG</span></div>${sampleControls()}<div class="panel-body"><div class="model-stage"><div><div class="chart-title">${t('Алғашқы 12 ағаш','Первые 12 деревьев','The first 12 trees')}</div><div class="forest-grid">${p.rfTrees.map((v,i)=>`<div class="mini-tree" style="--delay:${i*65}ms"><small>TREE ${String(i+1).padStart(2,'0')}</small><svg viewBox="0 0 80 50" aria-hidden="true"><path d="M40 8v11M40 19 20 30M40 19 60 30M20 30 10 43M20 30 30 43M60 30 50 43M60 30 70 43" fill="none" stroke="${colors[i%3]}" stroke-width="1.7"/><g fill="${colors[i%3]}"><circle cx="40" cy="8" r="4"/><circle cx="20" cy="30" r="3"/><circle cx="60" cy="30" r="3"/><circle cx="10" cy="43" r="3"/><circle cx="30" cy="43" r="3"/><circle cx="50" cy="43" r="3"/><circle cx="70" cy="43" r="3"/></g></svg><b>${fmt(v,1)} <small>MPG</small></b></div>`).join('')}</div><p class="footnote">${t('Көріністе 12 ағаш қана. Қорытынды барлық ағаштан есептелген; жауаптар категориялық дауыс емес, сандар.','Показаны только 12 деревьев. Итог вычислен по всем деревьям: это среднее чисел, а не голосование за класс.','Only 12 trees are shown. The final result averages predictions from every tree; these are numbers, not class votes.')}</p><div class="formula-card">ŷ = (ŷ₁ + ŷ₂ + … + ŷ${count}) / ${count}</div></div><div>${prediction('rf')}${metrics('rf')}${params('rf')}</div></div></div>`;}
function boostCurve(id){const p=selected(),rounds=data.models[id].stageRounds,vs=p[id==='gb'?'gbStages':'xgbStages'],maxRound=rounds.at(-1),minY=Math.floor(Math.min(p.y,...vs,id==='gb'?data.gbStart:vs[0])-2),maxY=Math.ceil(Math.max(p.y,...vs,id==='gb'?data.gbStart:vs[0])+2),x=v=>43+v/maxRound*375,y=v=>191-(v-minY)/(maxY-minY)*155;const pts=id==='gb'?[[0,data.gbStart],...vs.map((v,i)=>[rounds[i],v])]:vs.map((v,i)=>[rounds[i],v]);return `<svg viewBox="0 0 450 229" role="img" aria-label="${t('Қадам сайын MPG болжамы','Прогноз MPG по шагам','MPG prediction across boosting rounds')}">${[minY,(minY+maxY)/2,maxY].map(v=>`<path d="M43 ${y(v)}H418" stroke="#dce5d4"/><text x="35" y="${y(v)+3}" text-anchor="end" class="chart-label">${fmt(v,1)}</text>`).join('')}<text x="43" y="17" class="chart-label">MPG</text><path d="M43 ${y(p.y)}H418" stroke="#8b70af" stroke-dasharray="5 4" stroke-width="2"/><path d="${pts.map(([r,v],i)=>`${i?'L':'M'}${x(r)},${y(v)}`).join(' ')}" fill="none" stroke="#176e59" stroke-width="2.8"/><path d="M${x(rounds[stage[id]])} 30V191" stroke="#82947a" stroke-dasharray="3 4"/><circle cx="${x(rounds[stage[id]])}" cy="${y(vs[stage[id]])}" r="5" fill="#176e59" stroke="#fff" stroke-width="2"/>${[0,maxRound/2,maxRound].map(v=>`<text x="${x(v)}" y="213" class="chart-label" text-anchor="middle">${v}</text>`).join('')}</svg>`;}
function boostVisual(id){const m=data.models[id],rounds=m.stageRounds,pred=selected()[id==='gb'?'gbStages':'xgbStages'][stage[id]];return `<div class="panel-heading"><div><h2>${id==='gb'?t('Қалдық қатені біртіндеп түзету','Постепенно исправляем остатки','Fit residuals step by step'):t('XGBoost: реттелген бустинг','XGBoost: бустинг с регуляризацией','XGBoost: regularized boosting')}</h2><p>${m.params.n_estimators} ${t('ағаш / бустинг қадамы','деревьев / шагов бустинга','trees / boosting rounds')} · learning_rate=${m.params.learning_rate}</p></div><span class="status-chip">CV RMSE · ${fmt(m.cvRMSE)} MPG</span></div>${sampleControls()}<div class="panel-body"><div class="model-stage"><div><div class="boost-top"><div class="round-number"><span id="boostRound">${rounds[stage[id]]}</span><small> / ${rounds.at(-1)}</small></div><div class="boost-controls"><label for="stageRange">${t('Бустинг қадамын таңда','Выберите шаг бустинга','Choose a boosting round')}</label><input id="stageRange" type="range" min="0" max="${rounds.length-1}" step="1" value="${stage[id]}" aria-valuetext="${rounds[stage[id]]}"><div class="range-ends"><span>1</span><span>${rounds.at(-1)}</span></div></div></div><div class="chart-card"><div class="chart-title">${t('Бір автомобильдің болжамы','Прогноз одного автомобиля','One car’s prediction')}</div><div id="boostChart">${boostCurve(id)}</div><div class="legend"><span><i class="dot" style="background:#176e59"></i>${t('Болжам','Прогноз','Prediction')}</span><span><i class="dot" style="background:#8b70af"></i>${t('Нақты MPG','Фактическое MPG','Actual MPG')}</span></div></div><div class="boost-dots" id="boostDots">${Array.from({length:rounds.at(-1)},(_,i)=>`<i class="${i<rounds[stage[id]]?'on':''}"></i>`).join('')}</div><p class="footnote">${id==='gb'?t('Бастапқы болжам — train MPG орташа мәні','Начальный прогноз — среднее MPG на train','Initial prediction is the mean training MPG')+`: ${fmt(data.gbStart)} MPG. `:''}${t('Әр белгі — бір ағаш қосылған қадам. Графиктегі мәндер нақты модельден алынған.','Каждая отметка — шаг добавления дерева. Значения графика получены из обученной модели.','Each mark is one tree added. Chart values are actual fitted-model predictions.')}</p><div class="formula-card">${id==='gb'?'Fₘ(x) = Fₘ₋₁(x) + η · hₘ(x)':'Objective = prediction loss + regularization'}</div></div><div><div id="boostOutput">${prediction(id,pred)}</div>${metrics(id)}${params(id)}<p class="footnote">${t('Қадамдар бір автомобильдің қатесін әрдайым азайтпайды. Метрикалар толық, соңғы ансамбльге қатысты.','Ошибка отдельной машины не обязана уменьшаться на каждом шаге. Метрики относятся к полному итоговому ансамблю.','An individual car’s error need not decrease at every round. Metrics refer to the final full ensemble.')}</p><button class="button small" data-action="worstExample" data-value="${id}">${t('Ең үлкен қатені көр','Показать наибольшую ошибку','Inspect the largest error')} ↗</button></div></div></div>`;}
function updateBoost(id){const m=data.models[id],rounds=m.stageRounds;document.getElementById('boostRound').textContent=rounds[stage[id]];const el=document.getElementById('stageRange');el.value=stage[id];el.setAttribute('aria-valuetext',String(rounds[stage[id]]));document.getElementById('boostChart').innerHTML=boostCurve(id);document.getElementById('boostOutput').innerHTML=prediction(id,selected()[id==='gb'?'gbStages':'xgbStages'][stage[id]]);document.querySelectorAll('#boostDots i').forEach((e,i)=>e.classList.toggle('on',i<rounds[stage[id]]));}
function testScatter(){const x=v=>42+v/55*370,y=v=>254-v/55*220;return `<svg viewBox="0 0 445 297" role="img" aria-label="${t('80 автомобильдің нақты және болжанған MPG','Фактическое и предсказанное MPG 80 автомобилей','Actual and predicted MPG for 80 test cars')}">${[0,10,20,30,40,50].map(v=>`<path d="M42 ${y(v)}H412" stroke="#dce5d4"/><text x="35" y="${y(v)+3}" text-anchor="end" class="chart-label">${v}</text><text x="${x(v)}" y="273" text-anchor="middle" class="chart-label">${v}</text>`).join('')}<path d="M42 254 412 34" stroke="#879a80" stroke-dasharray="5 4"/><text x="42" y="18" class="chart-label">${t('Болжам','Прогноз','Predicted')} MPG</text><text x="226" y="295" text-anchor="middle" class="chart-label">${t('Нақты','Факт','Actual')} MPG</text>${data.test.map(p=>`<circle cx="${x(p.y)}" cy="${y(p.pred[compareModel])}" r="3.8" fill="${colors[p.x[6]-1]}" opacity=".75"><title>#${p.csvRow} ${esc(p.name)} · ${fmt(p.y)} → ${fmt(p.pred[compareModel])}</title></circle>`).join('')}</svg>`;}
function compareChart(){const max=Math.ceil(Math.max(...ids.flatMap(id=>[data.models[id].cvRMSE,data.models[id].rmse])));return `<div class="legend"><span><i class="dot" style="background:#adc9a5"></i>CV RMSE</span><span><i class="dot" style="background:#176e59"></i>Test RMSE</span><span>${t('MPG · аз болғаны жақсы','MPG · меньше лучше','MPG · lower is better')}</span></div><div class="compare-chart">${ids.map((id,i)=>{const m=data.models[id];return `<div class="compare-row"><div class="compare-name">${short[id]}</div><div class="compare-bars">${['cvRMSE','rmse'].map((key,j)=>`<div class="compare-bar"><div class="track"><span class="fill" style="--value:${m[key]/max*100}%;--color:${j?'#176e59':'#adc9a5'};--delay:${i*100+j*50}ms"></span></div><b>${fmt(m[key])}</b></div>`).join('')}</div></div>`;}).join('')}<div class="compare-scale">${[0,.25,.5,.75,1].map(v=>`<span>${fmt(max*v,1)}</span>`).join('')}</div></div>`;}
function modelTable(){return `<div class="table-scroll"><table class="data-table metric-table"><thead><tr><th>${t('Модель','Модель','Model')}</th><th>CV RMSE ↓</th><th>Test MAE ↓</th><th>Test RMSE ↓</th><th>Test R² ↑</th></tr></thead><tbody>${ids.map(id=>{const m=data.models[id];return `<tr class="${id===data.testWinner?'best-row':''}"><td>${short[id]}${id===data.testWinner?' ★':''}</td><td>${fmt(m.cvRMSE,4)}</td><td>${fmt(m.mae)}</td><td>${fmt(m.rmse)}</td><td>${fmt(m.r2,3)}</td></tr>`;}).join('')}<tr class="baseline-row"><td>Dummy · ${t('train орташа','среднее train','training mean')}</td><td>—</td><td>${fmt(data.baseline.mae)}</td><td>${fmt(data.baseline.rmse)}</td><td>${fmt(data.baseline.r2,3)}</td></tr></tbody></table></div>`;}
function comparisonVisual(){return `<div class="panel-heading"><div><h2>${t('Қай модельдің қатесі аз?','У какой модели ошибка меньше?','Which model has the smallest error?')}</h2><p>${t('Бірдей 318 train · 5-fold CV · 80 test','Общие 318 train · 5-fold CV · 80 test','Same 318 train · 5-fold CV · 80 test')}</p></div><button class="button small" data-action="play">▷ ${t('Салыстыру','Сравнить','Compare')}</button></div><div class="panel-body"><div class="winner-band"><div><small>${t('ЕҢ АЗ TEST RMSE','МИНИМАЛЬНЫЙ TEST RMSE','LOWEST TEST RMSE')}</small><strong>${short[data.testWinner]} · ${fmt(data.models[data.testWinner].rmse)} MPG</strong><p>${t('Осы 80 автомобильдегі бақылау нәтижесі','Наблюдаемый результат на этих 80 машинах','Observed result on these 80 cars')}</p></div><div><small>${t('TRAIN CV БОЙЫНША ТАҢДАУ','ВЫБОР ПО TRAIN CV','SELECTION BY TRAIN CV')}</small><strong>${short[data.cvWinner]} · ${fmt(data.models[data.cvWinner].cvRMSE,4)} MPG</strong><p>${t('Бес бөліктегі орташа RMSE','Среднее RMSE пяти блоков','Mean RMSE across five folds')}</p></div></div>${compareChart()}<div class="model-results">${modelTable()}</div><p class="footnote">${t('CV нәтижелері өте жақын: Gradient Boosting','Результаты CV почти совпадают: Gradient Boosting','The CV results are very close: Gradient Boosting')} ${fmt(data.models.gb.cvRMSE,5)} / XGBoost ${fmt(data.models.xgb.cvRMSE,5)} MPG. ${t('Айырмашылық 0,001 MPG-ден аз; біреуін барлық жағдайда үздік деуге болмайды.','Разница меньше 0,001 MPG; это не основание считать один алгоритм лучшим во всех задачах.','The difference is below 0.001 MPG; it does not establish a universally better algorithm.')}</p><p class="footnote">${t('MAE және RMSE — MPG бірлігіндегі қате: аз болғаны жақсы. R² — пайыз емес, өлшемсіз көрсеткіш; жоғарысы жақсы, кейде теріс болады.','MAE и RMSE — ошибки в MPG: меньше лучше. R² — не проценты, а безразмерный показатель; выше лучше, значение может быть отрицательным.','MAE and RMSE measure error in MPG: lower is better. R² is unitless, not a percentage; higher is better and it can be negative.')}</p><div class="compare-bottom"><div class="chart-card"><label class="chart-title" for="compareModel">${t('Нақты мән мен болжам','Факт и прогноз','Actual versus predicted')}</label><select id="compareModel" class="matrix-controls">${ids.map(id=>`<option value="${id}" ${compareModel===id?'selected':''}>${short[id]}</option>`).join('')}</select><div id="testScatter">${testScatter()}</div>${legend()}<p class="chart-sub">${t('Үзік сызық — мінсіз болжам. Нүкте одан алыс болса, қате үлкен.','Пунктир — идеальный прогноз. Чем дальше точка от него, тем больше ошибка.','The dashed line is a perfect prediction. Farther points have larger errors.')}</p></div><div><h3>${t('Тест таңдауға қатыспайды','Тест не участвует в выборе','The test set does not guide selection')}</h3><p class="footnote">${t('Әр модельде 8 параметр комбинациясы бірдей 5 CV бөлігінде тексерілді. Импутация мен one-hot Pipeline ішінде орындалды. Соңында ғана бөлек 80 автомобильге болжам жасалды.','Для каждой модели 8 комбинаций параметров проверялись на одинаковых 5 блоках CV. Импутация и one-hot выполнялись внутри Pipeline. Затем модели оценили на 80 отложенных машинах.','Each model’s 8 parameter combinations used the same 5 CV folds. Imputation and one-hot encoding stayed inside the Pipeline. Only then were models evaluated on 80 held-out cars.')}</p><div class="params"><code>GridSearchCV</code><code>KFold(5)</code><code>random_state=42</code></div><hr class="section-divider"><h3>${t('Бұл — регрессия','Это регрессия','This is regression')}</h3><p class="footnote">${t('MPG — үздіксіз сан. Сондықтан Accuracy немесе кластардың қателер матрицасы қолданылмайды. Бір test бөлігіндегі жеңіс барлық деректерге кепілдік емес.','MPG — непрерывное число. Поэтому здесь нет Accuracy и матрицы ошибок классов. Победа на одном test не гарантирует лучший результат на любых данных.','MPG is a continuous number, so classification accuracy and confusion matrices do not apply. A win on one test split does not guarantee the best result on all data.')}</p><div class="fold-scores" id="foldScores">${foldScores()}</div></div></div><div class="model-results"><div class="panel-heading" style="padding:15px 0"><h2>${t('80 автомобильдің жауабы','Прогнозы 80 автомобилей','Predictions for all 80 cars')}</h2>${tabs('worstOnly',[['all',t('Барлығы','Все','All')],['worst',t('Ірі 10 қате','10 наибольших ошибок','10 largest errors')]],worstOnly?'worst':'all')}</div><p class="footnote">${t('Қате бойынша сұрыптау таңдалған модельге қатысты','Сортировка ошибок относится к выбранной выше модели','Error ranking uses the model selected above')}: <b id="rankModel">${short[compareModel]}</b>. ${t('Әр ұяшықта болжам және |қате| көрсетілген.','В ячейках показаны прогноз и |ошибка|.','Each cell shows prediction and |error|.')}</p><div id="predictionRows"></div></div></div>`;}
function foldScores(){const m=data.models[compareModel],max=Math.max(...m.cvFolds);return `<p class="chart-title">${short[compareModel]} · CV RMSE (${t('5 бөлік','5 блоков','5 folds')})</p>${m.cvFolds.map((v,i)=>`<div class="fold-row"><span>${i+1}</span><div class="track"><span class="fill" style="--value:${v/max*100}%;--color:#8b70af"></span></div><b>${fmt(v)}</b></div>`).join('')}<p class="chart-sub">${t('Орташа','Среднее','Mean')}: ${fmt(m.cvRMSE)} · std: ${fmt(m.cvStd)} MPG</p>`;}
function drawPredictions(){let rows=data.test.slice();if(worstOnly)rows.sort((a,b)=>Math.abs(b.pred[compareModel]-b.y)-Math.abs(a.pred[compareModel]-a.y));if(worstOnly)rows=rows.slice(0,10);document.getElementById('predictionRows').innerHTML=`<div class="table-scroll" style="max-height:350px"><table class="data-table"><thead><tr><th>CSV</th><th>${t('Автомобиль','Автомобиль','Car')}</th><th>${t('Нақты MPG','Факт MPG','Actual MPG')}</th>${ids.map(id=>`<th>${short[id]}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td><button class="button small" data-action="inspect" data-value="${data.test.indexOf(r)}">#${r.csvRow} ↗</button></td><td>${esc(r.name)}</td><td><b>${fmt(r.y)}</b></td>${ids.map(id=>`<td>${fmt(r.pred[id])}<small class="cell-error">|${fmt(Math.abs(r.pred[id]-r.y))}|</small></td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="footnote">${t('CSV жолын бассаң, сол автомобильдің таңдалған моделі ашылады.','Нажмите номер CSV, чтобы открыть выбранную модель для этой машины.','Click a CSV row to inspect that car with the selected model.')}</p>`;}
function renderVisual(){const focus=document.activeElement?.id;document.getElementById('workspace').innerHTML=chapter===1?(isDataset()?datasetTable():datasetOverview()):chapter===2?treeVisual():chapter===3?forestVisual():chapter===4?boostVisual('gb'):chapter===5?boostVisual('xgb'):comparisonVisual();if(chapter===1&&isDataset())drawRows();if(chapter===6)drawPredictions();if(focus)document.getElementById(focus)?.focus({preventScroll:true});}
function route(scroll=false){stop();const match=location.hash.match(/^#([1-6])$/);chapter=match?Number(match[1]):1;const c=isDataset()?{...copy.chapters[0],title:t('Auto MPG датасеті','Датасет Auto MPG','Auto MPG dataset'),kicker:'DATASET / UCI AUTO MPG',heading:t('Auto MPG датасеті','Датасет Auto MPG','Auto MPG dataset'),intro:t('398 автомобильдің бастапқы деректері: MPG, жеті белгі және атауы. Кестеден ізде, сүзгіні қолдан және CSV файлын жүкте.','Исходные данные 398 автомобилей: MPG, семь признаков и название. Используйте поиск, фильтры и скачивание CSV.','Original data for 398 cars: MPG, seven input features and a name. Search, filter and download the CSV.')} : copy.chapters[chapter-1];document.title=`${c.title} · Auto MPG · ML LAB`;document.querySelectorAll('#chapterNav a').forEach(a=>{if(a.getAttribute('href')===(isDataset()?'#dataset':'#'+chapter))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});main.innerHTML=`<div class="lesson-head"><div><span class="eyebrow">${esc(c.kicker)}</span><h1>${esc(c.heading)}</h1><p>${esc(c.intro)}</p></div><span class="page-index">${isDataset()?'398':'0'+chapter}<span style="font-size:14px;letter-spacing:0">${isDataset()?' CSV':' / 06'}</span></span></div><div class="toolbar"><button class="button primary" data-action="code">&lt;/&gt; ${t('Осы беттің коды','Код этой страницы','Code for this page')}</button><button class="button" data-action="oral">◌ ${t('Түсіндірме','Объяснение','Explanation')}</button>${isDataset()?`<a class="button" href="autompg-files/auto_mpg.csv" download>↓ ${t('CSV жүктеу','Скачать CSV','Download CSV')}</a>`:`<a class="button" href="#dataset">▦ ${t('Датасетті ашу','Открыть датасет','Open dataset')}</a>`}<span class="verified-note">${t('Python-да есептелген нәтижелер. Анимация дайын модельдердің жұмысын көрсетеді.','Результаты рассчитаны в Python. Анимация показывает работу обученных моделей.','Computed in Python. Animations replay fitted model outputs.')}</span></div><section class="workspace" id="workspace" aria-label="${esc(c.title)}"></section><div class="insights">${c.steps.map((p,i)=>`<div class="insight"><span>0${i+1}</span><p>${esc(p)}</p></div>`).join('')}</div><div class="takeaway"><b>${t('ЕСТЕ САҚТА','ЗАПОМНИТЕ','TAKEAWAY')}</b>${esc(c.takeaway)}</div><div class="page-footer">${chapter>1?`<a class="button" href="#${chapter-1}">← ${t('Алдыңғы бет','Назад','Previous')}</a>`:`<a class="button" href="index${lang==='kk'?'':'.'+lang}.html#topics">← ML LAB</a>`}<small>AUTO MPG / ${String(chapter).padStart(2,'0')} OF 06</small>${chapter<6?`<a class="button primary" href="#${chapter+1}">${t('Келесі бет','Далее','Next page')} →</a>`:`<a class="button primary" href="autompg-files/Auto_MPG_Full_Lab.zip" download>↓ ${t('Толық жұмыс','Полная работа','Full lab')}</a>`}</div><footer class="source-links"><a href="https://archive.ics.uci.edu/dataset/9/auto%2Bmpg">UCI Auto MPG ↗</a><a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a><a href="autompg-files/auto_mpg.csv" download>CSV</a><a href="autompg-files/auto_mpg_4_models.py" download>Python</a><a href="autompg-files/Auto_MPG_4_Models_Akylbek.ipynb" download>Notebook</a><span>${t('Ақылбек & Алмас','Акылбек & Алмас','Akylbek & Almas')} · ML LAB</span></footer><p class="attribution">Quinlan, R. (1993). Auto MPG. UCI · DOI: 10.24432/C5859H. ${t('Бастапқы мәтін CSV-ге түрлендірілді; жетіспейтін мәндер сақталды.','Исходный текст преобразован в CSV; пропуски сохранены.','Source text converted to CSV; missing values preserved.')}</p>`;renderVisual();if(scroll){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}document.querySelector('#chapterNav [aria-current]')?.scrollIntoView({block:'nearest',inline:'nearest'});}
function stop(){if(timer){clearInterval(timer);timer=null;}}
function play(){stop();if(chapter===2){const nodes=[...document.querySelectorAll('.path-node')];if(reduced){nodes.forEach(n=>n.classList.add('shown'));return;}nodes.forEach(n=>n.classList.remove('shown'));let n=0;nodes[n++].classList.add('shown');timer=setInterval(()=>{nodes[n++]?.classList.add('shown');if(n>=nodes.length)stop();},650);}else if(chapter===4||chapter===5){const id=chapter===4?'gb':'xgb',last=data.models[id].stageRounds.length-1;stage[id]=reduced?last:0;updateBoost(id);if(!reduced)timer=setInterval(()=>{stage[id]++;updateBoost(id);if(stage[id]>=last)stop();},800);}else renderVisual();}
function openCode(){document.getElementById('dialogKicker').textContent='PYTHON / GOOGLE COLAB';document.getElementById('dialogTitle').textContent=copy.chapters[chapter-1].title;document.getElementById('dialogBody').innerHTML=`<p class="code-note">${t('Кодты Google Colab-тың бір ұяшығына көшіріп орында. Әр бет дербес іске қосылады. 2–5 беттер CV таңдаған параметрлерді қолданады; 6-бет GridSearchCV іздеуін қайта есептейді.','Скопируйте код в одну ячейку Google Colab. Каждая страница запускается отдельно. Страницы 2–5 используют параметры, выбранные CV; страница 6 заново выполняет GridSearchCV.','Paste the code into one Google Colab cell. Each page runs independently. Pages 2–5 use CV-selected parameters; page 6 reruns GridSearchCV.')}</p><div class="code-actions"><button class="button primary" id="copyCode">${t('Кодты көшіру','Копировать код','Copy code')}</button><a class="button" href="autompg-files/Auto_MPG_4_Models_Akylbek.ipynb" download>↓ Notebook</a><a class="button" href="autompg-files/auto_mpg_4_models.py" download>↓ Python</a></div><pre><code id="codeText"></code></pre><p class="toast" id="copyStatus" role="status"></p><p class="source-note">${t('Жүктелетін кодтың түсіндірмелері орысша. Нұсқалар notebook ішінде көрсетілген; кітапхана нұсқасы өзгерсе, нәтиже аздап өзгеруі мүмкін.','Комментарии загружаемого кода на русском. Версии указаны в notebook; при других версиях библиотек результат может немного отличаться.','Downloaded code includes Russian comments. Versions are recorded in the notebook; different library versions may slightly change results.')}</p>`;document.getElementById('codeText').textContent=codes[chapter-1].code;document.getElementById('copyCode').onclick=async()=>{try{await navigator.clipboard.writeText(codes[chapter-1].code);document.getElementById('copyStatus').textContent=t('Көшірілді ✓','Скопировано ✓','Copied ✓');}catch{const r=document.createRange();r.selectNodeContents(document.getElementById('codeText'));getSelection().removeAllRanges();getSelection().addRange(r);document.getElementById('copyStatus').textContent=t('Код белгіленді. Ctrl+C / ⌘C бас.','Код выделен. Нажмите Ctrl+C / ⌘C.','Code selected. Press Ctrl+C / ⌘C.');}};dialog.showModal();}
function openOral(){document.getElementById('dialogKicker').textContent=t('ТҮСІНДІРМЕ','ОБЪЯСНЕНИЕ','EXPLANATION');document.getElementById('dialogTitle').textContent=copy.chapters[chapter-1].title;document.getElementById('dialogBody').innerHTML=`<p class="oral-copy">${esc(copy.chapters[chapter-1].intro)} ${esc(copy.chapters[chapter-1].steps.join(" "))}</p><p class="code-note">${t('Бір автомобильді таңдап, болжамды нақты MPG мәнімен салыстыр.','Выберите автомобиль и сравните прогноз с реальным MPG.','Choose a car and compare its prediction with the actual MPG.')}</p>`;dialog.showModal();}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'});});document.getElementById('closeDialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
main.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action,v=a.dataset.value;if(action==='code'){stop();openCode();}else if(action==='oral'){stop();openOral();}else if(action==='play')play();else if(action==='prevRows'||action==='nextRows'){page+=action==='prevRows'?-1:1;drawRows();}else if(action==='worstOnly'){worstOnly=v==='worst';renderVisual();}else if(action==='inspect'){sample=Number(v);location.hash='#'+(ids.indexOf(compareModel)+2);}else if(action==='worstExample'){stop();sample=data.test.reduce((best,p,i)=>Math.abs(p.pred[v]-p.y)>Math.abs(data.test[best].pred[v]-data.test[best].y)?i:best,0);stage[v]=data.models[v].stageRounds.length-1;renderVisual();}});
main.addEventListener('change',e=>{const el=e.target;if(el.id==='sampleSelect'){stop();sample=Number(el.value);renderVisual();}else if(el.id==='originFilter'){origin=el.value;page=0;drawRows();}else if(el.id==='pageSize'){pageSize=Number(el.value);page=0;drawRows();}else if(el.id==='missingOnly'){missingOnly=el.checked;page=0;drawRows();}else if(el.id==='compareModel'){compareModel=el.value;document.getElementById('testScatter').innerHTML=testScatter();document.getElementById('foldScores').innerHTML=foldScores();document.getElementById('rankModel').textContent=short[compareModel];drawPredictions();}});
main.addEventListener('input',e=>{if(e.target.id==='stageRange'){stop();const id=chapter===4?'gb':'xgb';stage[id]=Number(e.target.value);updateBoost(id);}else if(e.target.id==='rowSearch'){query=e.target.value;page=0;drawRows();}});
window.addEventListener('hashchange',()=>{if(data)route(true);});window.addEventListener('pagehide',stop);
document.getElementById('sidebarNote').textContent=t('6 бөлім · 4 регрессор · 398 автомобиль. Түсіндірме мен код әр бетте.','6 разделов · 4 регрессора · 398 машин. Объяснение и код на каждой странице.','6 chapters · 4 regressors · 398 cars. Explanation and code on every page.');
document.getElementById('chapterNav').innerHTML=copy.chapters.map((c,i)=>`<a href="#${i+1}"><span>0${i+1}</span>${esc(c.title)}</a>`).join('')+`<a class="dataset-nav" href="#dataset"><span>▦</span>${t('Датасет кестесі','Таблица датасета','Dataset table')}</a>`;
Promise.all(['autompg-data.json','autompg-code.json'].map(u=>fetch(u).then(r=>{if(!r.ok)throw Error(u);return r.json();}))).then(([d,c])=>{data=d;codes=c;stage.gb=d.models.gb.stageRounds.length-1;stage.xgb=d.models.xgb.stageRounds.length-1;compareModel=d.testWinner;route();}).catch(()=>{main.innerHTML=`<div class="error-box" role="alert"><h1>${t('Деректер жүктелмеді','Данные не загрузились','Data could not load')}</h1><p>${t('Бетті жаңарт немесе толық notebook-ті жүкте.','Обновите страницу или скачайте полный notebook.','Refresh the page or download the full notebook.')}</p><a class="button" href="autompg-files/Auto_MPG_4_Models_Akylbek.ipynb" download>↓ Notebook</a></div>`;});
})();
